function [d_psi_s_dq, i_s_abc, tau_M] = mfun_gradnet_machine(u_s_ab, psi_s_dq, w_M, theta_M, machine)
%MFUN_GRADNET_MACHINE Synchronous machine with a GradNet current map with
%   spatial harmonics (SpatialSaturatedSynchronousMachinePars) in rotor
%   coordinates, as SynchronousMachine of motulator. Generated by
%   motulator_export from the MATLAB port of motulator.
persistent par
if isempty(par)
    g = machine.current_map;
    current_map = gradnet(g.in_dim, g.mu_dim, g.W, g.b, g.mu_log, ...
        g.bias, g.activation, g.beta_log, g.p, g.in_base, g.out_base);
    par = struct('n_p', machine.n_p, 'R_s', machine.R_s, ...
        'current_map', current_map, 'k', machine.k, ...
        'psi_f', machine.psi_f);
end
psi = complex(psi_s_dq(1), psi_s_dq(2));
theta_m = par.n_p*theta_M;
[i_s_dq, tau_M] = machine_magnetic_map(par, psi, theta_m);
% Phase currents
i_s_abc = complex2abc(i_s_dq*exp(1i*theta_m));
% Voltage equation in rotor coordinates
d_psi = machine_flux_rhs(par, complex(u_s_ab(1), u_s_ab(2)), psi, theta_M, w_M);
d_psi_s_dq = [real(d_psi); imag(d_psi)];
end

function u_abc = complex2abc(u)
%COMPLEX2ABC Phase quantities (a column vector) from the space vector.
u_abc = [real(u); 0.5*(-real(u) + sqrt(3)*imag(u)); 0.5*(-real(u) - sqrt(3)*imag(u))];
end

function net = gradnet(in_dim, mu_dim, W, b, mu_log, bias, activation, beta_log, ...
    p, in_base, out_base)
%GRADNET GradNet from its parameters (the fields of the GradNet structs of the
%   model initialization), W being an embed_dim-by-in_dim matrix. The field mu has
%   the gains of the linear term, zero for the inputs beyond the first mu_dim.
mu = zeros(size(W, 2), 1);
n_mu = min(mu_dim, numel(mu_log));
mu(1:n_mu) = exp(mu_log(1:n_mu));
net = struct('in_dim', in_dim, 'mu_dim', mu_dim, 'embed_dim', size(W, 1), ...
    'W', W, 'b', b(:), 'mu', mu, 'bias', bias(:), 'activation', activation, ...
    'beta', exp(beta_log), 'p', p, 'in_base', in_base, 'out_base', out_base);
end

function [z, jac] = gradnet_forward(net, x, want_jac)
%GRADNET_FORWARD Output of the network for a per-unit input x (a column vector),
%   as GradNetFunction.__call__. If want_jac is true, the Jacobian matrix is
%   computed too. The Jacobians of both activations are of the form
%   c*(diag(d) - u*u^T), so the Jacobian of the network is
%   diag(mu) + c*(W^T diag(d) W - v*v^T) with v = W^T u.
W = net.W;
beta = net.beta;
% Module: W^T act(W x + b)
h = beta*(W*x + net.b);
if net.activation == 1
    % PNormGradient: x^q/(1 + sum(x^(q + 1)))^(q/(q + 1)) with q = p - 1
    q = net.p - 1;
    norm_ = 1 + sum(h.^(q + 1));
    norm_r = norm_^(q/(q + 1));
    c = beta*q/norm_r;
    d = h.^(q - 1);
    u = h.^q/sqrt(norm_);
    h = h.^q/norm_r;
else
    % Softmax
    h = exp(h - max(h));
    h = h/sum(h);
    c = beta;
    d = h;
    u = h;
end
% Linear term (for the first mu_dim inputs), bias, and the module
z = net.mu.*x + net.bias + W'*h;
jac = zeros(size(W, 2));
if want_jac
    v = W'*u;
    jac = diag(net.mu) + c*(W'*(d.*W) - v*v');
end
end

function y = gradnet_map(net, x)
%GRADNET_MAP Evaluate the map (FluxMap or CurrentMap in motulator), symmetrized
%   about the d-axis. The input and output are in SI units.
% Evaluate at the input and its conjugate, and symmetrize about the d-axis
x1 = [real(x); imag(x)]/net.in_base;
x2 = [x1(1); -x1(2)];
z1 = gradnet_forward(net, x1, false);
z2 = gradnet_forward(net, x2, false);
y = 0.5*((z1(1) + 1i*z1(2)) + conj(z2(1) + 1i*z2(2)));
y = y*net.out_base;
end

function [i_s, tau_m] = gradnet_current_map_harmonics(net, k, psi_s, theta_m)
%GRADNET_CURRENT_MAP_HARMONICS Evaluate the current map with spatial harmonics
%   (CurrentMapWithHarmonics in motulator) of order k. Returns the stator current
%   (A) in rotor coordinates and the electromagnetic torque (Nm) per pole pair.
% Evaluate at the input and its conjugate, and symmetrize about the d-axis
psi = psi_s/net.in_base;
exp_j_k_theta = exp(1i*k*theta_m);
x1 = [real(psi); imag(psi); real(exp_j_k_theta); imag(exp_j_k_theta)];
x2 = [x1(1); -x1(2); x1(3); -x1(4)];
z1 = gradnet_forward(net, x1, false);
z2 = gradnet_forward(net, x2, false);
i = 0.5*((z1(1) + 1i*z1(2)) + conj(z2(1) + 1i*z2(2)));
dW_dcos = 0.5*(z1(3) + z2(3));
dW_dsin = 0.5*(z1(4) - z2(4));
% Torque in per-unit values, including the reluctance torque due to the spatial
% harmonics
dW_dtheta = k*(real(exp_j_k_theta)*dW_dsin - imag(exp_j_k_theta)*dW_dcos);
tau = imag(i*conj(psi)) - dW_dtheta;
% Scale back to physical units
i_s = i*net.out_base;
tau_m = tau*1.5*net.in_base*net.out_base;
end

function psi_s = psi_s_dq(par, i_s)
%PSI_S_DQ Stator flux linkage as a function of the stator current.
if par.saturated
    psi_s = gradnet_map(par.flux_map, i_s);
else
    psi_s = par.L_d*real(i_s) + par.psi_f + 1i*par.L_q*imag(i_s);
end
end

function [i_s_dq, tau_M] = machine_magnetic_map(par, psi_s_dq, theta_m)
%MACHINE_MAGNETIC_MAP Stator current (A) in rotor coordinates and the
%   electromagnetic torque (Nm), as functions of the stator flux linkage (Vs) in
%   rotor coordinates and the electrical rotor angle (rad).
[i_s_dq, tau_m] = gradnet_current_map_harmonics(par.current_map, par.k, psi_s_dq, ...
    theta_m);
tau_M = par.n_p*tau_m;
end

function d_psi_s_dq = machine_flux_rhs(par, u_s_ab, psi_s_dq, theta_M, w_M)
%MACHINE_FLUX_RHS State derivative of the stator flux linkage (Vs) in rotor
%   coordinates, given the stator voltage (V) in stator coordinates and the
%   mechanical rotor angle and speed.
theta_m = par.n_p*theta_M;
i_s_dq = machine_magnetic_map(par, psi_s_dq, theta_m);
u_s_dq = u_s_ab*exp(-1i*theta_m);
d_psi_s_dq = u_s_dq - par.R_s*i_s_dq - 1i*par.n_p*w_M*psi_s_dq;
end
